mapper.select:
SELECT u.user_id AS userId, u.username, u.avatar, ( SELECT COUNT(*) FROM tb_jmz_orders o WHERE o.taker_id = u.user_id AND o.created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) ) AS orderCount30d, ( SELECT COUNT(*) FROM tb_jmz_orders o WHERE o.taker_id = u.user_id AND o.status = 5 AND o.created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) ) AS finishCount30d, ( SELECT IFNULL(ROUND(SUM(CASE WHEN o.manager_id IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*), 2), 0) FROM tb_jmz_orders o WHERE o.taker_id = u.user_id AND o.created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) ) AS managerRate30d FROM tb_jmz_user u INNER JOIN tb_jmz_user_game_boosting ug ON u.user_id = ug.user_id
u.is_boosting_enabled = 1
AND ug.game_id = #{gameId}
AND u.username LIKE CONCAT('%', #{username}, '%')
GROUP BY u.user_id, u.username, u.avatar ORDER BY orderCount30d DESC LIMIT #{offset}, #{pageSize}
